class Solution {
public:
    int minimumOperations(vector<int>& nums) {
        int i = 0, j = nums.size() - 1, answer = 0;
        long long left = nums[i], right = nums[j];
        while (i < j) {
            if (left == right) {
                if (++i >= --j) break;
                left = nums[i]; right = nums[j];
            } else if (left < right) {
                left += nums[++i]; ++answer;
            } else {
                right += nums[--j]; ++answer;
            }
        }
        return answer;
    }
};
